package main

import (
    "fmt"
    "time"
)

func main() {
    start := time.Date(2026, time.March, 8, 21, 30, 0, 0, time.UTC)
    end := start.Add(90 * time.Minute)
    fmt.Println(end.Format("2006-01-02 15:04"))
    fmt.Println(end.Sub(start))
    fmt.Println(end.Weekday())
}

